import{_ as e,o as t,c as a,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第三卷 潮汐 · 第66章上 笑场","description":"","frontmatter":{},"headers":[],"relativePath":"第66章_笑场.md","filePath":"第66章_笑场.md"}'),o={name:"第66章_笑场.md"};function r(n,p,s,c,i,l){return t(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第三卷-潮汐-·-第66章上-笑场" tabindex="-1">第三卷 潮汐 · 第66章上 笑场 <a class="header-anchor" href="#第三卷-潮汐-·-第66章上-笑场" aria-label="Permalink to &quot;第三卷 潮汐 · 第66章上 笑场&quot;">​</a></h1><blockquote><p>【小注：本章为江苒视角】那盘带子是怎么一路笑坏的，她的版本。接第65章长信二。</p></blockquote><p>傍晚放学，天边还剩一点薄光。南雾县的街道浸在潮湿里，梧桐叶落在宋阿婆的小店门口，踩上去软软的。</p><p>我抱着旧磁带跑进去时，陈默和顾远已经占好里间小桌，林小满踮脚去够柜子上的海盐糖，何晓把录音机摆在正中，神情严肃得像要开大会。</p><p>宋阿婆笑眯眯放下一碟梨，又退到外间织毛衣。</p><p>“都到齐了？”何晓清清嗓子，“今晚主题，诗朗诵B面首录。”</p><p>我举起磁带晃了晃，盒子上贴着林小满画的潮汐线。A面录满了课文，B面空着，留给我们自己。</p><p>沈聿推门进来，带进一阵凉风。额发被雾沾湿，手里拎着一袋叠纸星星的纸条。他在我旁边坐下，椅子吱呀一声，耳朵有点红。</p><p>“沈大诗人来了，今晚你打头。”陈默起哄。</p><p>“为何是我。”沈聿挑眉。</p><p>顾远把一页卷角的纸推过去，上面晕了一小块水痕，“因为字是你写的，只有你认得你的草书。”</p><p>那首诗是我们一人一句凑出来的，写雾，写潮，写南雾县的夜。</p><p>何晓按下录音键，红灯亮起，屋里安静了，只有磁带转动的沙沙声。梨的甜香浮着，混着雾的凉。</p><p>沈聿坐得端正，拿起纸清清喉咙，声音低低的，“第一句，我来起。雾散后，潮水漫过心口。”</p><p>我们屏住呼吸，林小满手里的糖纸都不敢响。</p><p>他皱眉凑近纸，“南雾的夜，藏着……咸咸的梦。”</p><p>陈默噗的一声笑出来，又赶紧捂住嘴，肩膀抖个不停。</p><p>我瞪他一眼。沈聿瞥他一眼，放慢语速，格外郑重，“我想把心事折成纸星星，投入……投入，海里？”</p><p>“是投入潮汐里。”林小满小声提醒。</p><p>沈聿一本正经重复，“投入潮汐里。许愿瓶里的糖，化成……”他停住了。我凑过去看，纸上有一滴水痕，糖字糊成一团，汐字多了一点，像汤的影子。</p><p>他犹豫一下，大声念出来，掷地有声，“许愿瓶里的糖，化成夕阳下的汤。”</p><p>屋里静了半秒。</p><p>顾远第一个拍桌，“汤？什么汤？梨汤还是鱼汤？”</p><p>陈默笑得滑到椅子下，捶着地板，“沈聿你饿了吧，念诗念出晚饭了。”</p><p>林小满差点喷出嘴里的糖，眼睛弯成月牙，“咸的还是甜的呀，要不要趁热喝。”</p><p>我笑得靠在他肩上起不来。他耳朵红起来，却端着架子敲桌子，“安静，诗人还没念完。”</p><p>何晓笑得手抖，还不忘把录音机往他那边推，“来，诗人继续，B面就靠这句留名了。”</p><p>沈聿深吸一口气，绷着声音念，“风吹过操场边的树，叶子……落了一地的心，事？”</p><p>“心事要连起来念。”我提醒他，笑得发颤。</p><p>他字正腔圆，“好，落了一地的心事，踩上去，咯吱咯吱响。”</p><p>陈默捏着嗓子学，顾远抱着肚子笑，“你背课文挺顺的，怎么一到自己的诗就结巴。”</p><p>沈聿诚恳解释，“纸被雾打湿了，笔画像游走了。”</p><p>林小满剥颗糖放在他掌心，“诗人润润喉，甜一甜就不结巴了。”</p><p>他把糖放进嘴里，腮帮鼓起一块，含糊说，“咸的，难怪念成汤。”</p><p>满屋又是一阵笑，连宋阿婆都探头进来，“什么汤呀，我这儿正好有梨水，热乎的。”</p><p>录音机还在转，红灯一闪一闪，把笑都收了进去，像涨潮一样漫上来。</p><p>沈聿等我们笑够，敲敲桌沿，“还有最后一句，很正经，关乎诗的尊严。”</p><p>我们努力憋住。林小满把脸埋进围巾，顾远咬住袖口，我靠着墙深呼吸。</p><p>他走到灯下，影子被拉得很长，用播音员一样的语调念，“愿潮汐记得，南雾记得，我记得，你……”他顿住，纸角卷了起来，最后一句被折住了。</p><p>“你什么？”全屋齐声问。</p><p>他把纸翻来翻去，耳尖红红的，“最后一句是谁写的，没写完。”</p><p>何晓心虚举手，“是我，当时没想出来，空着等灵感。”</p><p>“那你现在补一句。”沈聿把纸递给她。</p><p>何晓看看我，又看看沈聿，眼睛亮亮的，大声说，“你站在雾里，也很好看。”</p><p>沈聿愣了一下，耳根红到脖子，声音轻了很多，“你站在雾里，也很好看。”</p><p>屋里静了一瞬，随即爆出更大的笑。陈默吹起口哨，顾远拍桌，林小满把纸星星往我们头上撒，何晓对着录音机喊，“B面经典诞生。”</p><p>纸星星落下来，落在他肩头，落在我发间。我接住一颗，纸面微凉。</p><p>沈聿坐回来，低头剥第二颗糖，嘴角压不住上扬。他把一颗糖塞进我手心，指尖凉凉的，“给你留的，不许再笑了。”</p>',48)])])}const f=e(o,[["render",r]]);export{m as __pageData,f as default};
